nfun[mu_]:=D[pfun[mu],mu];
eps[mu_]:=mu nfun[mu]-pfun[mu];
enthalpyIdentity=FullSimplify[D[pfun[mu],mu]/D[Log[mu/mu0],mu]-(eps[mu]+pfun[mu]),Assumptions->mu>0&&mu0>0];
rh=-r(r-2m)/(m+4Pi r^3 p); mh=4Pi r^2 e rh;
du=FullSimplify[2r rh/.m->v r/.r^2->u];
dv=FullSimplify[(mh/r-m rh/r^2)/.m->v r/.r^2->u];
duCheck=FullSimplify[du+2u(1-2v)/(v+4Pi u p)];
dvCheck=FullSimplify[dv+(1-2v)(4Pi u e-v)/(v+4Pi u p)];
centerCoeff=FullSimplify[Limit[((m+4Pi r^3 p)/(r(r-2m))/r)/.m->4Pi e r^3/3,r->0]];
centerCheck=FullSimplify[centerCoeff/2-2Pi(e+3p)/3];
cm={{-(l+1),-l(l+1)},{-1,-l}}; regularCenter=Simplify[cm.{1,-1/l},Assumptions->l>0]; charPoly=Factor[Det[z IdentityMatrix[2]-cm]];
scaledW=FullSimplify[((k^2 r^2 Exp[la-2nu]r^l vv+np r^(l+1)ww)/chi-l(l+1)Exp[la]r^l vv-(l+1)r^l ww)/r^(l+1),Assumptions->r>0];
scaledWCheck=FullSimplify[scaledW-((np/chi-(l+1)/r)ww+(k^2 r Exp[la-2nu]/chi-l(l+1)Exp[la]/r)vv),Assumptions->r>0];
scaledVCheck=FullSimplify[(2np r^l vv-Exp[la]r^(l+1)ww/r^2-l r^(l-1)vv)/r^l-(-Exp[la]ww/r+(2np-l/r)vv),Assumptions->r>0];
aprP=n D[en[n],n]-en[n]; aprCheck=FullSimplify[D[aprP,n]/D[en[n],n]-n D[en[n],{n,2}]/D[en[n],n]];
aa=-np(1/chieq-1/chiad); n2=-c^2 Exp[2(nu-la)]np aa; buoyancyEq=Simplify[n2/.chiad->chieq];
